package emitter

import "errors"

// EmitEffectsArtifacts generates the effect-focused runtime artifacts:
// middleware wrappers, registry wiring, and autogenerated port test doubles.
func (e *Emitter) EmitEffectsArtifacts(ctx MainContext, infraValues map[string]any) error {
	errs := make([]error, 0, 3)
	if err := e.EmitEffectMiddleware(ctx); err != nil {
		errs = append(errs, err)
	}
	if err := e.EmitEffectRegistry(ctx, infraValues); err != nil {
		errs = append(errs, err)
	}
	if err := e.EmitPortMocks(); err != nil {
		errs = append(errs, err)
	}
	return errors.Join(errs...)
}
